/*
 * A290537  Let S be the sequence generated by these rules: 0 is in S, and if
 *          z is in S, then z + 1 and z * (1+i) are in S (where i denotes the
 *          imaginary unit), and duplicates are deleted as they occur; a(n) =
 *          the imaginary part of the n-th term of S.
 * https://oeis.org/A290537
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, look
 * Formula:   not stated
 * Range:     i8 n <= 3125, i16 n <= 10000, i32 n <= 10000, i64 n <= 10000,
 *            i128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generates a(n) for OEIS A290537.
   The sequence is the imaginary part of the nth element of the set
   S produced by: start with 0; for each z∈S add z+1 and z*(1+i),
   removing duplicates.  The elements are generated in breadth‑first
   order.  The function memoises the sequence across calls.  */

#include <stdlib.h>
#include <stdint.h>

/* The integer type used in the build (int8_t … int64_t, __int128,
   or an arbitrary‑precision integer class).  seq_t is supplied
   externally and must not be defined here. */
typedef seq_t seq_t;

/* The index type supplied by the build (unsigned 64‑bit). */
typedef idx_t idx_t;

/* Gaussian integer (re + im·i). */
typedef struct {
    seq_t re;
    seq_t im;
} gaussian_t;

/* The sequence already generated (0-based).  All indices are uint64_t
   because the build guarantees idx_t >= uint64_t. */
static gaussian_t *seq = NULL;   /* dynamic array of generated elements */
static size_t seq_len = 0;       /* current number of elements stored   */
static size_t seq_cap = 0;       /* capacity of the dynamic array       */
static size_t next_to_process = 0; /* index of the next element whose
                                      successors must be generated      */

/* Ensure that the dynamic array has room for at least new_cap elements. */
static void ensure_seq_capacity(size_t new_cap)
{
    if (seq_cap >= new_cap)
        return;
    size_t cap = seq_cap > 0 ? seq_cap : 64;
    while (cap < new_cap)
        cap <<= 1;
    gaussian_t *tmp = (gaussian_t *)realloc(seq, cap * sizeof(gaussian_t));
    if (!tmp && cap != 0) /* allocation failure */
        abort();
    seq = tmp;
    seq_cap = cap;
}

/* Return 1 if the candidate Gaussian integer is NOT already in the
   sequence; otherwise returns 0.  Searches linearly which is O(N)
   but fast enough for the required limits. */
static int add_unique_candidate(const gaussian_t *cand)
{
    for (size_t i = 0; i < seq_len; ++i) {
        if (seq[i].re == cand->re && seq[i].im == cand->im)
            return 0; /* duplicate */
    }
    /* new element */
    ensure_seq_capacity(seq_len + 1);
    seq[seq_len++] = *cand;
    return 1;
}

/* Main function requested.  Builds the sequence up to at least n
   elements and returns the imaginary part of the nth element. */
seq_t a(idx_t n)
{
    /* n is 1‑based in OEIS. */
    if (n == 0)
        return (seq_t)0;

    /* Initialise the data structures on the first call. */
    if (seq_len == 0) {
        ensure_seq_capacity(128);
        seq[0].re = seq[0].im = (seq_t)0; /* S(1) = 0 */
        seq_len = 1;
        next_to_process = 0;
    }

    /* Generate new elements until we have at least n of them. */
    while (seq_len < n) {
        if (next_to_process >= seq_len)
            break; /* Should not happen; would mean the sequence is exhausted. */
        const gaussian_t z = seq[next_to_process++];

        /* Candidate 1: z + 1 */
        gaussian_t cand1;
        cand1.re = z.re + (seq_t)1;
        cand1.im = z.im;
        add_unique_candidate(&cand1);

        /* Candidate 2: z * (1 + i) = (re - im) + (re + im)i */
        gaussian_t cand2;
        cand2.re = z.re - z.im;
        cand2.im = z.re + z.im;
        add_unique_candidate(&cand2);
    }

    return seq[n - 1].im;
}
